; cost.asm -- chapter 9: one of each arithmetic instruction
; generated by gen09.py
        INCLUDE "msx.inc"
        OUTPUT "cost.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
init:   di
        ld sp, SYS_AREA
        ld hl, value            ; a byte of the cartridge, to read
        ld de, $1234
        ld ix, $5678
t0:     add a,b
t1:     adc a,(hl)
t2:     sub $12
t3:     daa
t4:     neg
t5:     add hl,de
t6:     adc hl,de
t7:     sbc hl,de
t8:     add ix,de
t9:     inc hl
t10:
stop:   jr stop
value:  db $21
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
